using System;
using System.IO;
using System.Text;
using System.Linq;
using System.Threading;
using System.Collections.Generic;
using PadLauncher;
class ExternalTests {
    static int checks;
    static void Check(bool value,string name) {if(!value) throw new Exception(name); checks++;}
    public static void Main() {
        string root=Path.Combine(Path.GetTempPath(),"EpicTests-"+Guid.NewGuid().ToString("N")); Directory.CreateDirectory(root);
        Storage.Root=root;
        try {
            var reimportSettings=new Settings();
            foreach(string provider in new[]{"steam","epic","gog","ea","ubisoft","rockstar","battlenet"}) {
                string restoredId=provider+":restore";
                var restoreSettings=new Settings {ReplacedGameIds=new List<string>{restoredId,"other:keep"},EnabledCollectionIds=new List<string>{"all"},ArtworkOverrides=new Dictionary<string,string>{{restoredId,"chosen.png"}}};
                var restoreLibrary=new Library {Games=new List<Game>{new Game {Id="custom:keep",Source="custom"}}};
                var detectedLibrary=new Library {Games=new List<Game>{new Game {Id=restoredId,Source=provider}},Collections=new List<Collection>{new Collection {Id="source:"+provider,Source=provider,Games=new List<string>{restoredId}}}};
                LauncherLibrary.RestoreSource(restoreLibrary,detectedLibrary,restoreSettings,provider);
                LauncherLibrary.RestoreSource(restoreLibrary,detectedLibrary,restoreSettings,provider);
                Check(restoreLibrary.Games.Count==2 && restoreLibrary.Games.Count(g => g.Id==restoredId)==1 && restoreLibrary.Collections.Count==1,"Repeated restore recovers "+provider+" games without duplicates");
                Check(restoreSettings.ReplacedGameIds.SequenceEqual(new[]{"other:keep"}) && restoreSettings.EnabledCollectionIds.SequenceEqual(new[]{"all"}) && restoreSettings.ArtworkOverrides[restoredId]=="chosen.png","Restore preserves other exclusions, hidden lists and artwork for "+provider);
            }
            var currentSource=new Library {Games=new List<Game>{new Game {Id="epic:old",Source="epic",Name="Old"},new Game {Id="custom:keep",Source="custom",Name="Keep"}},Collections=new List<Collection>{new Collection {Id="source:epic",Name="Epic",Source="epic"}}};
            var freshSource=new Library {Games=new List<Game>{new Game {Id="epic:new",Source="epic",Name="New"}},Collections=new List<Collection>{new Collection {Id="source:epic",Name="Epic",Source="epic",Games=new List<string>{"epic:new"}}}};
            LauncherLibrary.MergeSource(currentSource,freshSource,reimportSettings,"epic"); LauncherLibrary.MergeSource(currentSource,freshSource,reimportSettings,"epic");
            Check(currentSource.Games.Count==2 && currentSource.Games.Any(g => g.Id=="custom:keep") && !currentSource.Games.Any(g => g.Id=="epic:old"),"Launcher reimport replaces only target source and preserves other games");
            Check(currentSource.Collections.Count==1 && currentSource.Games.Count(g => g.Id=="epic:new")==1,"Repeated launcher reimport creates no game or list duplicates");
            var steamSettings=new Settings {CustomGames=new List<CustomGame>{new CustomGame {Id="custom:steam",SteamShortcutKey="42:123"}},ListGameAdditions=new Dictionary<string,List<string>>{{"tag:old",new List<string>{"custom:steam"}}}};
            var steamCurrent=new Library {Collections=new List<Collection>{new Collection {Id="tag:old",Source="steam",Name="Old"}}};
            var steamFresh=new Library {UserId="42",Collections=new List<Collection>{new Collection {Id="tag:new",Name="New",Source="steam",Games=new List<string>{"123"}}}};
            LauncherLibrary.MergeSource(steamCurrent,steamFresh,steamSettings,"steam"); LauncherLibrary.MergeSource(steamCurrent,steamFresh,steamSettings,"steam");
            Check(steamCurrent.Collections.Count==1 && steamCurrent.Collections[0].Id=="tag:new","Steam collection reimport updates stable lists and removes deleted collections");
            Check(steamSettings.ListGameAdditions["tag:new"].SequenceEqual(new[]{"custom:steam"}) && steamSettings.ListGameAdditions["tag:old"].Count==0,"Steam reimport updates imported shortcut membership without duplicate or stale links");
            string install=Path.Combine(root,"game"); Directory.CreateDirectory(install); File.WriteAllText(Path.Combine(install,"game.exe"),"");
            var manifest=new Dictionary<string,object>{{"DisplayName","Amnesia:  The Dark Descent"},{"AppName","app"},{"CatalogNamespace","ns"},{"CatalogItemId","item"},{"InstallLocation",install},{"LaunchExecutable","game.exe"},{"AppCategories",new[]{"games"}}};
            string file=Path.Combine(root,"game.item"); File.WriteAllText(file,Storage.Json().Serialize(manifest));
            string catalog=Path.Combine(root,"catalog"); File.WriteAllText(catalog,Convert.ToBase64String(Encoding.UTF8.GetBytes("[{\"namespace\":\"ns\",\"id\":\"item\",\"keyImages\":[{\"url\":\"https://cdn1.epicgames.com/cover.jpg\",\"width\":860,\"height\":1148}]}]")));
            var warnings=new List<string>(); var games=EpicLibrary.Scan(root,catalog,warnings);
            Check(games.Count==1 && games[0].Name=="Amnesia: The Dark Descent","Installed Epic game and normalized name");
            Check(games[0].ArtworkUrl.EndsWith("cover.jpg"),"Base64 catalog portrait");
            Check(GameLaunch.UriFor(games[0]).Contains("ns%3Aitem%3Aapp"),"Epic launch identifiers escaped");
            string epicLauncher=Path.Combine(root,"EpicGamesLauncher.exe"); File.WriteAllText(epicLauncher,"");
            var epicSettings=new Settings {EpicLauncherPath=epicLauncher}; var epicStart=GameLaunch.StartInfo(games[0],epicSettings);
            Check(epicStart.FileName==epicLauncher && epicStart.Arguments.Contains("com.epicgames.launcher://apps/ns%3Aitem%3Aapp") && epicStart.UseShellExecute,"Saved Epic executable receives the native game URI");
            Check(EpicLibrary.ValidateLauncher(" ")==null,"Empty Epic launcher path restores automatic detection");
            bool invalidEpic=false; try {EpicLibrary.ValidateLauncher(Path.Combine(install,"game.exe"));} catch(ArgumentException) {invalidEpic=true;} Check(invalidEpic,"Epic path override rejects unrelated executables");
            Check(Storage.Json().Deserialize<Settings>(Storage.Json().Serialize(epicSettings)).EpicLauncherPath==epicLauncher,"Epic path override persists in settings");
            Check(GameLaunch.UriFor(new Game {LaunchId="18446744073709551615"}).EndsWith("18446744073709551615"),"64 bit Steam shortcut preserved");
            manifest["bIsIncompleteInstall"]=true; File.WriteAllText(file,Storage.Json().Serialize(manifest)); Check(EpicLibrary.Scan(root,catalog,warnings).Count==0,"Incomplete excluded");
            manifest["bIsIncompleteInstall"]=false; manifest["LaunchExecutable"]="../outside.exe"; File.WriteAllText(Path.Combine(root,"outside.exe"),""); File.WriteAllText(file,Storage.Json().Serialize(manifest)); Check(EpicLibrary.Scan(root,catalog,warnings).Count==0,"Traversal rejected");
            Check(!ArtworkNetwork.AllowedImageUrl("https://cdn1.epicgames.com.evil.test/x") && !ArtworkNetwork.AllowedImageUrl("http://cdn1.epicgames.com/x"),"Image host and HTTPS boundaries");
            ArtworkKey.Save("secret-test-key"); Check(ArtworkKey.Load()=="secret-test-key","DPAPI roundtrip"); Check(!Encoding.UTF8.GetString(File.ReadAllBytes(Path.Combine(root,"steamgriddb.key"))).Contains("secret-test-key"),"Key encrypted at rest"); ArtworkKey.Clear(); Check(ArtworkKey.Load()==null,"Key removal");
            string steamArt=Path.Combine(root,"custom-wide.png");
            using(var image=new System.Drawing.Bitmap(100,50)) image.Save(steamArt,System.Drawing.Imaging.ImageFormat.Png);
            var shortcutArt=new Game {Id="custom",Shortcut=true,Art=steamArt};
            Check(ArtworkService.KeepArtwork(shortcutArt),"Custom Steam shortcut artwork preserved regardless of dimensions");
            ArtworkService.ApplyCached(shortcutArt,new Settings());
            Check(shortcutArt.Art==steamArt,"Artwork cache never replaces existing Steam custom art");
            Check(!ArtworkService.KeepArtwork(new Game {Source="epic",Art=steamArt}),"Unsuitable Epic artwork can still use portrait fallback");
            Check(!ArtworkService.KeepArtwork(new Game {Id="missing",Art=Path.Combine(root,"missing.png")}),"Missing Steam artwork still eligible for fallback");
            int calls=0;
            ArtworkService.Fetch=(url,key,token) => {calls++; Check(key=="test","API bearer passed"); return Encoding.UTF8.GetBytes(url.Contains("autocomplete") ? "{\"success\":true,\"data\":[{\"id\":42,\"name\":\"Amnesia: The Dark Descent\"}]}" : "{\"success\":true,\"data\":[{\"url\":\"https://cdn2.steamgriddb.com/grid/test.png\"}]}");};
            Check(ArtworkService.FindGrid(games[0],"test",CancellationToken.None).Contains("test.png") && calls==2,"Exact SGDB match and portrait lookup");
            ArtworkService.Fetch=(url,key,token) => Encoding.UTF8.GetBytes("{\"success\":true,\"data\":[{\"id\":42,\"name\":\"Amnesia Collection\"}]}");
            Check(ArtworkService.FindGrid(games[0],"test",CancellationToken.None)==null,"Different edition never guessed");
            Console.WriteLine(checks+" external integration checks passed");
            var combinedSettings=new Settings {EnabledCollectionIds=new List<string>{"a","b"}};
            var collectionLibrary=new Library {Games=new List<Game>{new Game {Id="1"},new Game {Id="2"},new Game {Id="3"}},Collections=new List<Collection>{new Collection {Id="a",Name="First",Games=new List<string>{"1","2"}},new Collection {Id="b",Name="Second",Games=new List<string>{"2","3"}}}};
            string combinedId=CombinedCollections.Save(combinedSettings,collectionLibrary,null,"Together",new[]{"a","b"});
            Check(CombinedCollections.Options(collectionLibrary,combinedSettings).Last().Games.SequenceEqual(new[]{"1","2","3"}),"Union deduplicates shared games");
            Check(combinedSettings.EnabledCollectionIds.Contains(combinedId),"New combined collection automatically enabled");
            collectionLibrary.Collections[0].Games=new List<string>{"3"};
            Check(!CombinedCollections.Options(collectionLibrary,combinedSettings).Last().Games.Contains("1"),"Combined membership follows refreshed sources");
            CombinedCollections.Save(combinedSettings,collectionLibrary,combinedId,"Renamed",new[]{"a","all"});
            Check(combinedSettings.CombinedCollections.Count==1 && combinedSettings.CombinedCollections[0].Name=="Renamed","Editing keeps identity and replaces definition");
            var hiddenSettings=Storage.Json().Deserialize<Settings>(Storage.Json().Serialize(combinedSettings));
            hiddenSettings.EnabledCollectionIds.Remove(combinedId);
            CombinedCollections.Save(hiddenSettings,collectionLibrary,combinedId,"Renamed",new[]{"a","all"});
            Check(!hiddenSettings.EnabledCollectionIds.Contains(combinedId),"Editing a hidden combined list keeps it hidden");
            hiddenSettings.ListGameAdditions=new Dictionary<string,List<string>>{{combinedId,new List<string>{"1","2"}}};
            hiddenSettings.CombinedCollections[0].ExcludedGames=new List<string>{"2"};
            Check(!CombinedCollections.Options(collectionLibrary,hiddenSettings).Single(c => c.Id==combinedId).Games.Contains("2"),"Combined list exclusions also apply to saved additions");
            CustomLists.Save(hiddenSettings,collectionLibrary,combinedId,"Renamed",new[]{"3"});
            Check(CombinedCollections.Options(collectionLibrary,hiddenSettings).Single(c => c.Id==combinedId).Games.SequenceEqual(new[]{"3"}),"Removing a saved addition from a combined list stays removed");
            var restored=Storage.Json().Deserialize<Settings>(Storage.Json().Serialize(combinedSettings));
            Check(CombinedCollections.Options(collectionLibrary,restored).Last().Games.Count==3,"Definition persists and supports All games");
            bool rejected=false; try {CombinedCollections.Save(combinedSettings,collectionLibrary,null,"Bad",new[]{"a"});} catch(ArgumentException) {rejected=true;} Check(rejected,"At least two sources required");
            rejected=false; try {CombinedCollections.Save(combinedSettings,collectionLibrary,null,"Renamed",new[]{"a","b"});} catch(ArgumentException) {rejected=true;} Check(rejected,"Duplicate names rejected");
            rejected=false; try {CombinedCollections.Save(combinedSettings,collectionLibrary,combinedId,"Cycle",new[]{combinedId,"a"});} catch(ArgumentException) {rejected=true;} Check(rejected,"Combined sources cannot introduce cycles");
            collectionLibrary.Collections.Clear(); Check(CombinedCollections.Options(collectionLibrary,restored).Last().Games.Count==3,"Missing sources handled safely");
            Console.WriteLine("9 combined collection checks passed");
            var namedLists=new Library {Collections=new List<Collection>{new Collection {Id="user-collections.cached",Name="Installed",Games=new List<string>{"1"}},new Collection {Id="tag:Arcade",Name="Arcade"},new Collection {Id="source:epic",Name="Epic Games Store"},new Collection {Id="source:steam",Name="Steam",Source="steam"}}};
            var displayedLists=CombinedCollections.Options(namedLists,new Settings());
            Check(displayedLists.Single(c => c.Id=="user-collections.cached").Name=="Installed (Steam collection)" && displayedLists.Single(c => c.Id=="tag:Arcade").Name=="Arcade (Steam collection)","Cached Steam lists and shortcut tags get Steam labels");
            Check(namedLists.Collections[0].Name=="Installed" && displayedLists.Single(c => c.Id=="user-collections.cached").Games.Contains("1"),"Steam labels preserve source names, IDs and membership");
            Check(displayedLists.Single(c => c.Id=="source:epic").Name=="Epic Games Store" && displayedLists.Single(c => c.Id=="source:steam").Name=="Steam","Other launchers and the Steam source list keep clear names");
            Check(CombinedCollections.SteamListName(new Collection {Id="tag:test",Name="Arcade (Steam)"})=="Arcade (Steam collection)","Steam suffix is never duplicated");
            Console.WriteLine("4 list label checks passed");
            var emptySources=CombinedCollections.Options(new Library(),new Settings());
            Check(emptySources.Any(c => c.Id=="source:custom" && c.Games.Count==0) && emptySources.Any(c => c.Id=="source:gog" && c.Games.Count==0),"Empty Custom games and GOG lists remain available to combine");
            var futureSettings=new Settings(); string futureId=CombinedCollections.Save(futureSettings,new Library(),null,"PC future",new[]{"source:custom","source:gog"});
            var futureLibrary=new Library {Games=new List<Game>{new Game {Id="custom:later",Source="custom"},new Game {Id="gog:later",Source="gog"}}};
            Check(CombinedCollections.Options(futureLibrary,futureSettings).Single(c => c.Id==futureId).Games.Count==2,"Combining empty source lists automatically includes future detected games");
            Check(CombinedCollections.Options(namedLists,new Settings()).Count(c => c.Id=="source:steam")==1,"Permanent source lists never duplicate detected source entries");
            Console.WriteLine("3 empty source list checks passed");
            var countLibrary=new Library {Games=new List<Game>{new Game {Id="1"},new Game {Id="2"}}};
            var countList=new Collection {Id="sample",Name="Steam",Games=new List<string>{"1","1","not-installed"}};
            Check(CombinedCollections.Label(countList,countLibrary)=="Steam (1 game)","List labels count unique currently available games, excluding stale memberships");
            Check(CombinedCollections.Label(new Collection {Id="all",Name="All games"},countLibrary)=="All games (2 games)" && CombinedCollections.Label(new Collection {Id="empty",Name="Custom games"},countLibrary)=="Custom games (0 games)","All games and empty lists show correct counts");
            Check(countList.Name=="Steam","Game counts never modify the stored list name");
            Console.WriteLine("3 list game-count checks passed");
            var customSettings=new Settings();
            var custom=new CustomGame {Name="Standalone",Target=Path.Combine(install,"game.exe"),Arguments="--test \"two words\"",Artwork=steamArt};
            string customId=CustomGameLibrary.Save(customSettings,custom);
            var customLibrary=new Library(); CustomGameLibrary.Apply(customLibrary,customSettings);
            Check(customLibrary.Collections.Single().Id=="source:custom" && customLibrary.Games.Single().Source=="custom","Custom games get their own collection");
            var start=GameLaunch.StartInfo(customLibrary.Games.Single());
            Check(start.FileName==custom.Target && start.Arguments==custom.Arguments && start.WorkingDirectory==install,"Custom launch retains arguments and defaults working directory");
            Check(ArtworkService.KeepArtwork(customLibrary.Games.Single()),"Custom local artwork always preserved");
            custom=new CustomGame {Id=customId,Name="Renamed standalone",Target=custom.Target,WorkingDirectory=root}; CustomGameLibrary.Save(customSettings,custom); CustomGameLibrary.Apply(customLibrary,customSettings);
            Check(customLibrary.Games.Count==1 && customLibrary.Games[0].Id==customId && GameLaunch.StartInfo(customLibrary.Games[0]).WorkingDirectory==root,"Editing retains identity and replaces previous entry");
            var customRestored=Storage.Json().Deserialize<Settings>(Storage.Json().Serialize(customSettings)); Check(customRestored.CustomGames.Single().Name=="Renamed standalone","Custom games persist in settings");
            bool invalid=false; try {CustomGameLibrary.Save(customSettings,new CustomGame {Name="Invalid",Target=catalog});} catch(ArgumentException) {invalid=true;} Check(invalid,"Nonlaunchable target rejected");
            invalid=false; try {CustomGameLibrary.Save(customSettings,new CustomGame {Name="Invalid",Target=custom.Target,WorkingDirectory=Path.Combine(root,"absent")});} catch(ArgumentException) {invalid=true;} Check(invalid,"Missing working directory rejected");
            Check(!CustomGameLibrary.MissingTarget(custom),"Existing custom-game target is preserved");
            Check(CustomGameLibrary.MissingTarget(new CustomGame {Target=Path.Combine(install,"missing.exe")}),"Missing custom executable in a readable folder is detected");
            Check(CustomGameLibrary.MissingTarget(new CustomGame {Target=Path.Combine(root,"deleted-folder","missing.exe")}),"Custom games in deleted folders are detected");
            string offlineDrive=Enumerable.Range('D',23).Select(letter => ((char)letter)+@":\").First(drive => !DriveInfo.GetDrives().Any(existing => existing.Name.Equals(drive,StringComparison.OrdinalIgnoreCase)));
            Check(!CustomGameLibrary.MissingTarget(new CustomGame {Target=Path.Combine(offlineDrive,"Offline","missing.exe")}),"Custom games on disconnected drives are preserved");
            Check(!CustomGameLibrary.MissingTarget(new CustomGame {Target="steam://rungameid/123"}) && !CustomGameLibrary.MissingTarget(new CustomGame {Target=""}),"Non-file custom targets cannot be removed as missing files");
            var repairEntry=customSettings.CustomGames.Single();
            repairEntry.Arguments="--keep-arguments"; repairEntry.Artwork="artwork/manual.img";
            customSettings.CustomLists=new List<CustomList> {new CustomList {Id="repair-list",Name="Repair list",Games=new List<string>{customId}}};
            string repairedTarget=Path.Combine(root,"relocated.exe"); File.WriteAllText(repairedTarget,"");
            GameLaunch.RepairPath(customSettings,new Game {Id=customId,Source="custom"},repairedTarget);
            Check(repairEntry.Target==repairedTarget && repairEntry.Arguments=="--keep-arguments" && repairEntry.Artwork=="artwork/manual.img" && customSettings.CustomLists.Single().Games.Contains(customId),"Repairing a custom target preserves arguments, artwork, and list membership");
            customSettings.CustomGames.Clear(); CustomGameLibrary.Apply(customLibrary,customSettings);
            Check(customLibrary.Games.Count==0 && customLibrary.Collections.Count==0 && File.Exists(custom.Target),"Removing entry keeps game files");
            Console.WriteLine("8 custom game checks passed");
            var featureSettings=new Settings {LaunchHistory=new Dictionary<string,long>{{"epic:one",300},{"steam:one",50}}};
            var featureLibrary=new Library {Games=new List<Game>{new Game {Id="steam:one",Name="Steam",LastPlayed=200},new Game {Id="epic:one",Name="Epic"},new Game {Id="custom:none",Name="Unplayed"}}};
            var recent=CombinedCollections.Options(featureLibrary,featureSettings).Single(c => c.Id=="recent");
            Check(recent.Games.SequenceEqual(new[]{"epic:one","steam:one"}),"Recent collection merges local launch history and Steam history in newest-first order");
            Check(featureSettings.RightStickSpeed==5,"Settings without a saved speed default to 5x right stick speed");
            Check(StartupSetting.Command(Path.Combine(root,"Folder with spaces","Launcher.exe")).StartsWith("\"") && StartupSetting.Command(Path.Combine(root,"Folder with spaces","Launcher.exe")).EndsWith("\""),"Windows startup executable path is quoted");
            byte[] coverBytes;
            using(var cover=new System.Drawing.Bitmap(600,900)) using(var stream=new MemoryStream()) {cover.Save(stream,System.Drawing.Imaging.ImageFormat.Png); coverBytes=stream.ToArray();}
            ArtworkService.Fetch=(url,bearer,token) => {Check(bearer==null,"Artwork download never sends API key to image host"); return coverBytes;};
            var selectedGame=new Game {Id="pick",Art=steamArt}; string relativeCover=ArtworkService.SaveChoice(selectedGame,"https://cdn2.steamgriddb.com/grid/chosen.png",CancellationToken.None);
            featureSettings.ArtworkOverrides=new Dictionary<string,string>{{selectedGame.Id,relativeCover}};
            ArtworkService.ApplyCached(selectedGame,featureSettings);
            Check(selectedGame.Art==Path.Combine(Storage.Root,relativeCover) && selectedGame.ArtworkProvider=="chosen" && !Path.IsPathRooted(relativeCover),"Explicit artwork selection overrides existing art and stores a portable relative path");
            Check(File.Exists(steamArt),"Selecting artwork preserves original image");
            featureSettings.ArtworkOverrides.Clear(); selectedGame.Art=steamArt; ArtworkService.ApplyCached(selectedGame,featureSettings); Check(selectedGame.Art==steamArt,"Reset returns priority to original artwork");
            Console.WriteLine("7 launcher feature checks passed");
            Check(ArtworkService.OriginalGrid(new Game {Id="10"},null,CancellationToken.None)==ArtworkService.OriginalSteamUrl(10),"Native Steam original artwork works without an API key");
            Check(ArtworkService.OriginalGrid(new Game {Id="epic:test",Source="epic",ArtworkUrl="https://cdn1.epicgames.com/original.jpg"},null,CancellationToken.None).Contains("epicgames.com"),"Epic original cover uses catalog source");
            ArtworkService.Fetch=(url,bearer,token) => Encoding.UTF8.GetBytes(url.Contains("autocomplete") ? "{\"success\":true,\"data\":[{\"id\":42,\"name\":\"Standalone\"}]}" : "{\"success\":true,\"data\":{\"external_platform_data\":{\"steam\":[{\"id\":10}]}}}");
            Check(ArtworkService.OriginalGrid(new Game {Id="custom:test",Source="custom",Name="Standalone"},"test",CancellationToken.None)==ArtworkService.OriginalSteamUrl(10),"Standalone original artwork requires verified external Steam link");
            Console.WriteLine("3 original artwork checks passed");
            Check(ArtworkService.Normalize("Crash™ Team Racing Nitro-Fueled")==ArtworkService.Normalize("CTR: Crash Team Racing - Nitro-Fueled"),"Crash trademark and repeated acronym normalize to the same title");
            Check(ArtworkService.Normalize("Pokémon®: Café")==ArtworkService.Normalize("Pokemon Cafe"),"Accents and trademark symbols do not prevent matching");
            Check(ArtworkService.Normalize("DOOM Eternal")!=ArtworkService.Normalize("DOOM") && ArtworkService.Normalize("Game II")!=ArtworkService.Normalize("Game III"),"Sequels and subtitle distinctions preserved");
            Check(ArtworkService.ExactMatch("Crash Team Racing Nitro Fueled",new[]{new ArtworkGameMatch {Id=5246172,Name="CTR: Crash Team Racing - Nitro-Fueled"},new ArtworkGameMatch {Id=36474,Name="CTR (Crash Team Racing)"}})==5246172,"Original Crash Team Racing cannot be confused with Nitro-Fueled");
            Check(ArtworkService.ExactMatch("Game",new[]{new ArtworkGameMatch {Id=1,Name="Game"},new ArtworkGameMatch {Id=2,Name="Game"}})==0,"Ambiguous matches require manual choice");
            string observedQuery=null;
            ArtworkService.Fetch=(url,bearer,token) => {observedQuery=url; return Encoding.UTF8.GetBytes("{\"success\":true,\"data\":[{\"id\":5246172,\"name\":\"CTR: Crash Team Racing - Nitro-Fueled\"}]}");};
            Check(ArtworkService.SearchGames("Crash™ Team Racing Nitro-Fueled","test",CancellationToken.None).Count==1 && !observedQuery.Contains("%E2%84%A2"),"Search request strips trademark symbols before reaching SGDB");
            Console.WriteLine("6 artwork matching checks passed");
            ArtworkService.Fetch=(url,bearer,token) => Encoding.UTF8.GetBytes(Uri.UnescapeDataString(url).EndsWith("/warhammer",StringComparison.OrdinalIgnoreCase) ? "{\"success\":true,\"data\":[{\"id\":1,\"name\":\"Warhammer: Vermintide\"}]}" : "{\"success\":true,\"data\":[{\"id\":5331738,\"name\":\"Warhammer 40,000: Boltgun\"}]}");
            var broad=ArtworkService.SearchForPicker(new Game {Id="shortcut",Shortcut=true,Name="Warhammer 40,000 Boltgun"},"warhammer","test",CancellationToken.None);
            Check(broad.Count==2 && broad[0].Id==5331738,"Broad artwork search retains current exact match even if autocomplete omitted it");
            Check(broad.Select(g => g.Id).Distinct().Count()==broad.Count,"Merged artwork suggestions contain no duplicates");
            ArtworkService.Fetch=(url,bearer,token) => Encoding.UTF8.GetBytes(Uri.UnescapeDataString(url).Contains("40,000") ? "{\"success\":true,\"data\":[{\"id\":5331738,\"name\":\"Warhammer 40,000: Boltgun\"}]}" : "{\"success\":true,\"data\":[]}");
            Check(ArtworkService.ExactMatch("Warhammer 40,000 Boltgun",ArtworkService.SearchGames("Warhammer 40,000 Boltgun","test",CancellationToken.None))==5331738,"Punctuation-preserving search fallback handles numeric title separators");
            Console.WriteLine("3 broad artwork search checks passed");
            string firstPortable=Path.Combine(root,"first-portable"),secondPortable=Path.Combine(root,"second-portable");
            Storage.Root=firstPortable; Storage.InitializePortable();
            Storage.Write("settings.json",new Settings {ButtonPrompts="Xbox",CustomGames=customRestored.CustomGames});
            Storage.Root=secondPortable; Storage.InitializePortable();
            Check(Directory.Exists(secondPortable) && Directory.GetFileSystemEntries(secondPortable).Length==0,"Fresh portable data folder starts empty");
            Check(Storage.Read<Settings>("settings.json")==null,"Fresh copy cannot inherit settings from another installation");
            Storage.Write("settings.json",new Settings {ButtonPrompts="Nintendo"});
            Storage.InitializePortable();
            Check(Storage.Read<Settings>("settings.json").ButtonPrompts=="Nintendo","Portable initialization preserves its own settings");
            Storage.Root=firstPortable;
            Check(Storage.Read<Settings>("settings.json").ButtonPrompts=="Xbox","Portable installations keep independent settings");
            Console.WriteLine("4 portable isolation checks passed");
            Console.WriteLine("4 Epic path checks included above");
            ArtworkService.Fetch=(url,bearer,token) => Encoding.UTF8.GetBytes(url.Contains("autocomplete") ? "{\"success\":true,\"data\":[{\"id\":35404,\"name\":\"Crash Bandicoot 3: Warped\"}]}" : "{\"success\":true,\"data\":[{\"url\":\"https://cdn2.steamgriddb.com/grid/crash3.png\",\"width\":600,\"height\":900}]}");
            Check(ArtworkService.FindGrid(new Game {Id="crash3",Source="emulator",Name="Crash Bandicoot 3"},"test",CancellationToken.None).EndsWith("crash3.png"),"Crash Bandicoot 3 matches SteamGridDB's numbered Warped title");
        } finally {Directory.Delete(root,true);}
    }
}
